// ❌ DANGEROUS: No base case
function countdown(n) {
  console.log(n);
  countdown(n - 1); // Infinite stack frames!
}

// ✅ CORRECT: Explicit base case guard
function countdown(n) {
  if (n <= 0) { // Base Case
    console.log("Done!");
    return;
  }
  console.log(n);
  countdown(n - 1); // Converges toward base case
}
